  $prodQ=$db->prepare("SELECT p.id,p.sku,p.description,p.unit,p.cost_usd,COALESCE(pc.name,'Otros') category FROM products p LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE p.id=? AND p.active=1");$items=[];$materials=0;$sort=0;
  foreach($_POST['items']??[] as $r){$productId=(int)($r['product_id']??0);$qty=(float)($r['quantity']??0);if(!$productId||$qty<=0)continue;$prodQ->execute([$productId]);$p=$prodQ->fetch();if(!$p)continue;$unit=round((float)$p['cost_usd']*(1+$markup/100),2);$sub=round($qty*$unit,2);$materials+=$sub;$items[]=[$productId,$p['category'],brandFromCategory($p['category']),$p['sku'],$p['description'],$p['unit'],$qty,$unit,$listId,$sub,$sort++];}
  if(!$items)throw new Exception('Agregá al menos un producto.');
