  $db->beginTransaction();
  if($a==='update_quote'){
   if(!$qid)throw new Exception('Presupuesto inválido.');
   $db->prepare('UPDATE quotes SET project_id=?,version_no=?,quote_category=?,currency="USD",quote_date=?,quote_families=?,quote_template_family=?,price_list_id=?,materials_amount=?,labor_amount=?,labor_description=?,subtotal=?,tax_mode="sin_iva",vat_rate=21,materials_tax_mode=?,materials_vat_rate=?,labor_tax_mode=?,labor_vat_rate=?,total=?,status=?,notes=? WHERE id=?')->execute([$pid,$version,$category,$date,implode(',',$families),$template,$listId,$materials,$labor,$laborDescription,$materials+$labor,$matMode,$matVat,$labMode,$labVat,$total,$status,$notes,$qid]);$db->prepare('DELETE FROM quote_items WHERE quote_id=?')->execute([$qid]);
  }else{
   $db->prepare('INSERT INTO quotes(project_id,version_no,quote_category,currency,quote_date,quote_families,quote_template_family,price_list_id,materials_amount,labor_amount,labor_description,subtotal,tax_mode,vat_rate,materials_tax_mode,materials_vat_rate,labor_tax_mode,labor_vat_rate,total,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$pid,$version,$category,'USD',$date,implode(',',$families),$template,$listId,$materials,$labor,$laborDescription,$materials+$labor,'sin_iva',21,$matMode,$matVat,$labMode,$labVat,$total,$status,$notes]);$qid=(int)$db->lastInsertId();
