<div class="card"><div class="actions"><div style="flex:1"><h2>Equipamiento</h2></div><button class="btn" type="button" onclick="addRow()">+ Agregar producto</button></div><div style="overflow:auto"><table><thead><tr><th style="width:180px">SKU</th><th>Descripción</th><th>Marca</th><th style="width:90px">Cant.</th><th class="right">Precio USD</th><th class="right">Subtotal</th><th></th></tr></thead><tbody id="items"></tbody></table></div><div class="totals"><div><span>Materiales</span><b id="materials">US$ 0,00</b></div></div></div>
<div class="card grid"><p class="c6"><label>Descripción de mano de obra</label><select id="laborPreset" onchange="applyLaborPreset(this.value)"><option value="">Seleccionar descripción (lista a completar)</option><option value="__manual__">Otra / escribir manualmente</option></select><input style="margin-top:8px" id="laborDescription" name="labor_description" value="<?=e($q['labor_description']??'')?>" placeholder="Ej.: Instalación, programación y puesta en marcha"></p><p class="c3"><label>Mano de obra USD</label><input id="labor" type="number" min="0" step=".01" name="labor_amount" value="<?=e($q['labor_amount'])?>"></p><p class="c3"><label>Estado</label><select name="status"><?php foreach(['borrador'=>'Borrador','aprobado_inicial'=>'Aprobado inicial','final'=>'Final'] as $v=>$t):?><option value="<?=$v?>" <?=$q['status']===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></p><p class="c3"><label>IVA materiales</label><select name="materials_tax_mode"><?php foreach(['sin_iva'=>'Sin IVA','mas_iva'=>'+ IVA','iva_incluido'=>'IVA incluido'] as $v=>$t):?><option value="<?=$v?>" <?=$q['materials_tax_mode']===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></p><p class="c3"><label>% IVA materiales</label><input type="number" step=".01" name="materials_vat_rate" value="<?=e($q['materials_vat_rate'])?>"></p><p class="c3"><label>IVA mano de obra</label><select name="labor_tax_mode"><?php foreach(['sin_iva'=>'Sin IVA','mas_iva'=>'+ IVA','iva_incluido'=>'IVA incluido'] as $v=>$t):?><option value="<?=$v?>" <?=$q['labor_tax_mode']===$v?'selected':''?>><?=$t?></option><?php endforeach;?></select></p><p class="c3"><label>% IVA mano de obra</label><input type="number" step=".01" name="labor_vat_rate" value="<?=e($q['labor_vat_rate'])?>"></p><p class="c12"><label>Notas</label><textarea name="notes"><?=e($q['notes'])?></textarea></p></div><button class="btn"><?=$editing?'Guardar cambios':'Guardar presupuesto'?></button></form>
<script>const products=<?=json_encode($productJson,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,lists=<?=json_encode($listJson)?>;let row=0;const money=n=>'US$ '+Number(n||0).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function productPrice(id){const p=products[id],l=lists[document.getElementById('priceList').value];return p&&l?Math.round(p.cost*(1+l.markup/100)*100)/100:0}function searchProducts(q){q=String(q||'').toLowerCase().trim();if(!q)return Object.values(products).slice(0,20);return Object.values(products).filter(p=>p.sku.toLowerCase().includes(q)||p.description.toLowerCase().includes(q)).slice(0,30)}function renderSuggestions(input){const wrap=input.closest('.suggest-wrap'),box=wrap.querySelector('.suggestions'),matches=searchProducts(input.value);box.innerHTML=matches.map(p=>`<div class="suggestion" data-id="${p.id}"><b>${esc(p.sku)}</b><span>${esc(p.description)}</span></div>`).join('')||'<div class="suggestion">Sin coincidencias</div>';box.style.display='block';box.querySelectorAll('[data-id]').forEach(el=>el.onmousedown=e=>{e.preventDefault();selectProduct(input.closest('tr'),el.dataset.id)})}function selectProduct(tr,id){const p=products[id];if(!p)return;tr.dataset.product=id;tr.querySelector('.product-id').value=id;tr.querySelector('.sku-input').value=p.sku;tr.querySelector('.desc-input').value=p.description;tr.querySelector('.brand').textContent=p.brand;tr.querySelectorAll('.suggestions').forEach(x=>x.style.display='none');calc()}function bindSearch(inp){inp.addEventListener('input',()=>{inp.closest('tr').dataset.product='';inp.closest('tr').querySelector('.product-id').value='';renderSuggestions(inp);calc()});inp.addEventListener('focus',()=>renderSuggestions(inp));inp.addEventListener('blur',()=>setTimeout(()=>inp.closest('.suggest-wrap').querySelector('.suggestions').style.display='none',120))}function addRow(productId=null,qty=1){const i=row++,tr=document.createElement('tr');tr.innerHTML=`<td><input class="product-id" type="hidden" name="items[${i}][product_id]"><div class="suggest-wrap"><input class="sku-input" placeholder="Buscar SKU"><div class="suggestions"></div></div></td><td><div class="suggest-wrap"><input class="desc-input" placeholder="Buscar descripción"><div class="suggestions"></div></div></td><td class="brand">—</td><td><input class="qty" type="number" min=".01" step=".01" name="items[${i}][quantity]" value="${qty}" oninput="calc()"></td><td class="right price">—</td><td class="right sub">—</td><td><button class="btn remove" type="button" onclick="this.closest('tr').remove();calc()">×</button></td>`;document.getElementById('items').appendChild(tr);bindSearch(tr.querySelector('.sku-input'));bindSearch(tr.querySelector('.desc-input'));if(productId)selectProduct(tr,String(productId))}function calc(){let total=0;document.querySelectorAll('#items tr').forEach(tr=>{const id=tr.dataset.product,price=productPrice(id),qty=Number(tr.querySelector('.qty').value||0),sub=price*qty;tr.querySelector('.price').textContent=id?money(price):'—';tr.querySelector('.sub').textContent=id?money(sub):'—';if(id)total+=sub});document.getElementById('materials').textContent=money(total)}function filterProjects(){const c=document.getElementById('client').value,p=document.getElementById('project');[...p.options].forEach((o,i)=>{if(i===0)return;o.hidden=o.dataset.client!==c});if(p.selectedOptions[0]&&p.selectedOptions[0].hidden)p.value=''}function applyLaborPreset(v){if(v&&v!=='__manual__')document.getElementById('laborDescription').value=v;else if(v==='__manual__')document.getElementById('laborDescription').focus()}document.getElementById('client').addEventListener('change',filterProjects);document.getElementById('priceList').addEventListener('change',calc);filterProjects();<?php if($editItems):?><?php foreach($editItems as $it):?>addRow(<?=json_encode((int)$it['product_id'])?>,<?=json_encode((float)$it['quantity'])?>);<?php endforeach;?><?php else:?>addRow();<?php endif;?></script></main></body></html>
